package routing

import (
	"fmt"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/steveyegge/beads/internal/git"
)

var gitCommandRunner = func(repoPath string, args ...string) ([]byte, error) {
	cmd := exec.Command("git", args...)
	if repoPath != "" {
		cmd.Dir = repoPath
	}
	return cmd.Output()
}

// UserRole represents whether the user is a maintainer or contributor
type UserRole string

const (
	Maintainer  UserRole = "maintainer"
	Contributor UserRole = "contributor"
)

// DetectUserRole determines if the user is a maintainer or contributor
// based on git configuration and repository permissions.
//
// Detection strategy:
// 1. Check git config for beads.role setting (preferred source of truth)
// 2. Fall back to URL heuristic with deprecation warning (graceful degradation)
// 3. Default to maintainer for local projects (no remote configured)
func DetectUserRole(repoPath string) (UserRole, error) {
	// First check for explicit role in git config (preferred source)
	if role, ok := roleFromGitConfig(repoPath); ok {
		return role, nil
	}

	// jj secondary workspaces have no .git of their own, so the lookup above
	// fails even when the primary workspace has beads.role set. Resolve the
	// primary workspace and retry there, then run the remaining fallbacks
	// against the primary's git repo since the secondary has no usable git
	// context. The resolution is anchored at repoPath (not cwd) so it stays
	// consistent with the git-config lookup above. (GH#2950)
	if _, isSecondary := git.JJSecondaryWorkspaceRootFrom(repoPath); isSecondary {
		if primaryRoot, err := git.GetJJPrimaryWorkspaceRootFrom(repoPath); err == nil {
			if role, ok := roleFromGitConfig(primaryRoot); ok {
				return role, nil
			}
			repoPath = primaryRoot
		}
	}

	// Fallback to URL heuristic (deprecated, with warning)
	// This keeps existing users working while encouraging migration
	fmt.Fprintln(os.Stderr, "warning: beads.role not configured (GH#2950).")
	fmt.Fprintln(os.Stderr, "  Fix: git config beads.role maintainer")
	fmt.Fprintln(os.Stderr, "  Or:  git config beads.role contributor")
	return detectFromURL(repoPath), nil
}

// roleFromGitConfig reads beads.role from the git config of repoPath.
// Returns (role, true) only for a valid explicit value; (_, false) when the
// config is unset, git is unavailable, or the value is not a recognized role.
func roleFromGitConfig(repoPath string) (UserRole, bool) {
	output, err := gitCommandRunner(repoPath, "config", "--get", "beads.role")
	if err != nil {
		return "", false
	}
	switch UserRole(strings.TrimSpace(string(output))) {
	case Maintainer:
		return Maintainer, true
	case Contributor:
		return Contributor, true
	}
	return "", false
}

// detectFromURL uses remote URL patterns to infer user role.
// This heuristic is deprecated - SSH URLs don't reliably indicate write access
// (e.g., fork contributors often use SSH).
func detectFromURL(repoPath string) UserRole {
	originURL, hasOrigin := getOriginURL(repoPath)
	if !hasOrigin {
		// No remote means local project - default to maintainer
		return Maintainer
	}

	// Fork heuristic: if both origin and upstream are configured and point to
	// different repos, user is almost certainly contributing via fork workflow.
	if upstreamOutput, err := gitCommandRunner(repoPath, "remote", "get-url", "upstream"); err == nil {
		upstreamURL := strings.TrimSpace(string(upstreamOutput))
		if upstreamURL != "" && !sameRemoteRepository(originURL, upstreamURL) {
			return Contributor
		}
	}

	// Check if URL indicates write access
	// SSH URLs (git@github.com:user/repo.git) typically indicate write access
	// HTTPS with token/password also indicates write access
	if strings.HasPrefix(originURL, "git@") ||
		strings.HasPrefix(originURL, "ssh://") ||
		strings.Contains(originURL, "@") {
		return Maintainer
	}

	// HTTPS without credentials likely means read-only contributor
	return Contributor
}

func getOriginURL(repoPath string) (string, bool) {
	output, err := gitCommandRunner(repoPath, "remote", "get-url", "--push", "origin")
	if err != nil {
		// Fallback to standard fetch URL if push URL fails (some git versions/configs)
		output, err = gitCommandRunner(repoPath, "remote", "get-url", "origin")
		if err != nil {
			return "", false
		}
	}
	return strings.TrimSpace(string(output)), true
}

func sameRemoteRepository(a, b string) bool {
	slugA, okA := remoteRepositorySlug(a)
	slugB, okB := remoteRepositorySlug(b)
	if okA && okB {
		return slugA == slugB
	}
	return strings.TrimSpace(a) == strings.TrimSpace(b)
}

func remoteRepositorySlug(remote string) (string, bool) {
	remote = strings.TrimSpace(strings.TrimSuffix(remote, "/"))
	if remote == "" {
		return "", false
	}

	// SCP-like URL: git@github.com:owner/repo.git
	if strings.Contains(remote, "@") && strings.Contains(remote, ":") && !strings.Contains(remote, "://") {
		parts := strings.SplitN(remote, ":", 2)
		if len(parts) != 2 {
			return "", false
		}
		return normalizeRemotePath(parts[1])
	}

	u, err := url.Parse(remote)
	if err != nil {
		return "", false
	}
	return normalizeRemotePath(u.Path)
}

func normalizeRemotePath(path string) (string, bool) {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	path = strings.TrimSuffix(path, ".git")
	if path == "" {
		return "", false
	}
	return path, true
}

// RoutingConfig defines routing rules for issues
type RoutingConfig struct {
	Mode             string // "auto" or "explicit"
	DefaultRepo      string // Default repo for new issues
	MaintainerRepo   string // Repo for maintainers (in auto mode)
	ContributorRepo  string // Repo for contributors (in auto mode)
	ExplicitOverride string // Explicit --repo flag override
}

// RoutingRule identifies which clause of DetermineTargetRepo matched, so
// callers can explain *why* a repo was routed instead of assuming a single
// cause (e.g. the contributor-role rule).
type RoutingRule int

const (
	// RuleNone means no routing rule matched; the current repo was used.
	RuleNone RoutingRule = iota
	// RuleExplicitOverride means config.ExplicitOverride took precedence.
	RuleExplicitOverride
	// RuleMaintainer means auto mode routed via MaintainerRepo for a
	// maintainer-role user.
	RuleMaintainer
	// RuleContributor means auto mode routed via ContributorRepo for a
	// contributor-role user.
package main

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/steveyegge/beads/internal/config"
	"github.com/steveyegge/beads/internal/debug"
	"github.com/steveyegge/beads/internal/routing"
	"github.com/steveyegge/beads/internal/storage"
)

var routingConfigKeys = []string{
	"routing.mode",
	"routing.contributor",
	"routing.default",
	"routing.maintainer",
	"contributor.auto_route",
	"contributor.planning_repo",
}

func resolveRoutingConfigValue(key string, dbValues map[string]string) string {
	if src := config.GetValueSource(key); src != config.SourceDefault {
		if value := strings.TrimSpace(config.GetString(key)); value != "" {
			return value
		}
	}
	return strings.TrimSpace(dbValues[key])
}

func getRoutingConfigValue(ctx context.Context, store storage.DoltStorage, key string) string {
	if src := config.GetValueSource(key); src != config.SourceDefault {
		if value := strings.TrimSpace(config.GetString(key)); value != "" {
			return value
		}
	}
	if store == nil {
		return ""
	}
	dbValue, err := store.GetConfig(ctx, key)
	if err != nil {
		debug.Logf("DEBUG: failed to read config %q from store: %v\n", key, err)
		return ""
	}
	return strings.TrimSpace(dbValue)
}

func determineAutoRoutedRepoPath(ctx context.Context, store storage.DoltStorage) (string, routing.RoutingRule) {
	userRole, err := routing.DetectUserRole(".")
	if err != nil {
		debug.Logf("Warning: failed to detect user role: %v\n", err)
	}

	var dbValues map[string]string
	if store != nil {
		all, allErr := store.GetAllConfig(ctx)
		if allErr != nil {
			debug.Logf("DEBUG: failed to read config from store: %v\n", allErr)
		} else {
			dbValues = make(map[string]string, len(routingConfigKeys))
			for _, key := range routingConfigKeys {
				if v, ok := all[key]; ok {
					dbValues[key] = v
				}
			}
		}
	}

	routingMode := resolveRoutingConfigValue("routing.mode", dbValues)
	contributorRepo := resolveRoutingConfigValue("routing.contributor", dbValues)

	if routingMode == "" {
		if resolveRoutingConfigValue("contributor.auto_route", dbValues) == "true" {
			routingMode = "auto"
		}
	}
	if contributorRepo == "" {
		contributorRepo = resolveRoutingConfigValue("contributor.planning_repo", dbValues)
	}

	routingConfig := &routing.RoutingConfig{
		Mode:             routingMode,
		DefaultRepo:      resolveRoutingConfigValue("routing.default", dbValues),
		MaintainerRepo:   resolveRoutingConfigValue("routing.maintainer", dbValues),
		ContributorRepo:  contributorRepo,
		ExplicitOverride: "",
	}

	return routing.DetermineTargetRepoWithRule(routingConfig, userRole, ".")
}

// routingNoticeText returns the stderr note and remediation command for the
// given routing rule, so the notice always attributes the swap to the rule
// that actually matched instead of hardcoding the contributor-role case.
func routingNoticeText(rule routing.RoutingRule) (reason, fix string) {
	switch rule {
	case routing.RuleContributor:
		// The contributor rule fires on explicit beads.role=contributor OR on
		// origin-URL inference with beads.role unset — don't claim the config
		// key is set when it may not be.
		return "contributor routing (beads.role=contributor, or inferred from the origin URL) routes bd list/ready to the contributor planning store, not this project",
			"git config beads.role maintainer"
	case routing.RuleMaintainer:
		return "routing.maintainer routes bd list/ready to a different planning store than this project",
			"bd config unset routing.maintainer"
	case routing.RuleDefault:
		return "routing.default routes bd list/ready to a different planning store than this project",
			"bd config unset routing.default"
	default:
		return "an auto-routing rule sends bd list/ready to a different planning store than this project",
			"bd config get routing.mode routing.contributor routing.maintainer routing.default"
	}
}

// printContributorRoutingNotice tells the user that `bd list`/`bd ready` are
// reading from an auto-routed store instead of the local project database,
// so a short or empty result doesn't look like data loss. Without this, a
// routed-but-unrelated (often empty) planning store silently replaces the
// local result set with no indication anything changed: `bd stats` and
// `bd show <id>` don't route (see openRoutedReadStore callers), so they keep
// reporting the local project truth while list/ready go quiet — exactly the
// split that makes this so hard to diagnose from the CLI alone.

