func TestOutputJSONWithPagination_NoTruncation(t *testing.T) {
	items := []string{"a", "b"}
	out := captureStdout(t, func() error {
		return outputJSONWithPagination(items, nil)
	})
	var arr []string
	if err := json.Unmarshal([]byte(bytes.TrimSpace([]byte(out))), &arr); err != nil {
