		{"git@github.com:org/repo.git", true},
		{"deploy@myserver.com:beads/data", true},

		// Local paths — should return false
		{".", false},
		{"..", false},
		{"~/beads-planning", false},
		{"/absolute/path/to/repo", false},
		{"../relative/path", false},
		{"relative/path", false},
		{"", false},
		{"/", false},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
